insert into questions (id, certification_id, prompt, theory, topic, difficulty, position, published) values
('20000000-0000-0000-0000-000000000201','10000000-0000-0000-0000-000000000003','What is an LLM?','A large language model is trained on large amounts of text and code to understand and generate language, including programming assistance.', 'AI fundamentals', 'Level 1', 1, true),
('20000000-0000-0000-0000-000000000202','10000000-0000-0000-0000-000000000003','Which prompt is best for asking AI to write a Java function?','Effective prompts state the language, required behaviour, output type and useful constraints such as tests.', 'Prompting', 'Level 1', 2, true),
('20000000-0000-0000-0000-000000000203','10000000-0000-0000-0000-000000000003','What should a developer do before merging AI-generated code?','The developer remains responsible for the code. Review it, understand it, test it and apply normal code-review practices.', 'Code quality', 'Level 1', 3, true),
('20000000-0000-0000-0000-000000000204','10000000-0000-0000-0000-000000000003','Why can AI-generated code be risky?','Generated code can contain defects, insecure patterns, incorrect assumptions or APIs that do not exist in the project version.', 'Code quality', 'Level 1', 4, true),
('20000000-0000-0000-0000-000000000205','10000000-0000-0000-0000-000000000003','Which information should never be pasted into a public AI tool?','Keep API keys, passwords, customer data and other confidential material out of public AI tools unless your organisation has approved controls.', 'Security', 'Level 1', 5, true),
('20000000-0000-0000-0000-000000000206','10000000-0000-0000-0000-000000000003','What is an AI hallucination in a programming context?','A hallucination is a confident but incorrect output, such as an invented library method, API or explanation.', 'Reliability', 'Level 1', 6, true),
('20000000-0000-0000-0000-000000000207','10000000-0000-0000-0000-000000000003','What does it mean to use an AI model through an API?','An application can send input to an AI service and receive structured or unstructured output programmatically through an API.', 'AI integration', 'Level 1', 7, true),
('20000000-0000-0000-0000-000000000208','10000000-0000-0000-0000-000000000003','What is RAG?','Retrieval-augmented generation retrieves relevant trusted information before a model produces an answer, helping ground responses in useful context.', 'AI integration', 'Level 1', 8, true),
('20000000-0000-0000-0000-000000000209','10000000-0000-0000-0000-000000000003','What are embeddings commonly used for?','Embeddings represent the meaning of text or other data as numbers, enabling semantic search and similarity matching.', 'AI integration', 'Level 1', 9, true),
('20000000-0000-0000-0000-000000000210','10000000-0000-0000-0000-000000000003','What does responsible AI-assisted development require?','Developers should keep ownership of the outcome: review outputs, test behaviour, protect sensitive information and apply security checks.', 'Responsible AI', 'Level 1', 10, true);
